5	/**
6	 * Formats a stored E.164 telephone for humans: the country code, a space, then the national
7	 * digits grouped in threes (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
8	 */
9	public final class TelephoneDisplay {
10	
11	    private TelephoneDisplay() {
12	    }
13	
14	    /** The human-formatted display of {@code owner}'s E.164 telephone. */
15	    public static String of(Owner owner) {
16	        return format(owner.getTelephone());
17	    }
18	
19	    /** {@code e164} with its national digits grouped in threes; returned unchanged when not E.164. */
20	    static String format(String e164) {
21	        if (e164 == null || !e164.startsWith("+")) {
22	            return e164;
23	        }
24	        int cc = e164.startsWith("+1") ? 2 : 3; // '+1' has a 1-digit country code, others 2 digits
25	        String national = e164.substring(cc);
26	        StringBuilder out = new StringBuilder(e164.substring(0, cc));
27	        for (int i = 0; i < national.length(); i += 3) {
28	            out.append(' ').append(national, i, Math.min(i + 3, national.length()));
29	        }
30	        return out.toString();
31	    }
